import{_ as s,o as i,c as t,a2 as e}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"安装与启动","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":null}'),n={name:"guide/installation.md"};function l(h,a,p,o,r,d){return i(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="安装与启动" tabindex="-1">安装与启动 <a class="header-anchor" href="#安装与启动" aria-label="Permalink to &quot;安装与启动&quot;">​</a></h1><p>本文介绍如何在 Linux / Windows 服务器上从零部署 Northstar 平台。</p><h2 id="环境准备" tabindex="-1">环境准备 <a class="header-anchor" href="#环境准备" aria-label="Permalink to &quot;环境准备&quot;">​</a></h2><h3 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h3><p><strong>硬件最低配置</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>CPU</td><td>2 核</td></tr><tr><td>内存</td><td>4G</td></tr><tr><td>磁盘</td><td>10G</td></tr><tr><td>网络</td><td>100Mbps</td></tr></tbody></table><p><strong>软件依赖</strong></p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>JDK</td><td>25（9.1.x 版本；旧版本为 JDK 21）</td></tr></tbody></table><h3 id="环境脚本安装" tabindex="-1">环境脚本安装 <a class="header-anchor" href="#环境脚本安装" aria-label="Permalink to &quot;环境脚本安装&quot;">​</a></h3><p>执行对应的环境安装脚本，自动安装环境依赖（JDK）。</p><h4 id="linux-环境" tabindex="-1">Linux 环境 <a class="header-anchor" href="#linux-环境" aria-label="Permalink to &quot;Linux 环境&quot;">​</a></h4><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://pro.quantit.tech/assets/env.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><h4 id="windows-环境" tabindex="-1">Windows 环境 <a class="header-anchor" href="#windows-环境" aria-label="Permalink to &quot;Windows 环境&quot;">​</a></h4><p>打开 <code>powershell</code> 命令行环境，输入以下命令：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-WebRequest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pro.quantit.tech</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">assets</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutFile env.ps1; powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">noexit </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.\\env.ps1&quot;</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>假如执行报错，需要把脚本下载到本地后右键选择 powershell 执行。</p></div><h3 id="安装后的路径说明" tabindex="-1">安装后的路径说明 <a class="header-anchor" href="#安装后的路径说明" aria-label="Permalink to &quot;安装后的路径说明&quot;">​</a></h3><ul><li><strong>Linux</strong> 环境下，根目录是 <code>~/</code></li><li><strong>Windows</strong> 环境下，根目录是 <code>c:/</code></li></ul><p>安装完成后的目录结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── northstar-dist      # 程序目录</span></span>
<span class="line"><span>└── northstar-env       # 运行环境目录</span></span></code></pre></div><h3 id="软件包下载" tabindex="-1">软件包下载 <a class="header-anchor" href="#软件包下载" aria-label="Permalink to &quot;软件包下载&quot;">​</a></h3><p>下载地址：<a href="https://gitee.com/dromara/northstar/releases" target="_blank" rel="noreferrer">https://gitee.com/dromara/northstar/releases</a></p><p>下载后，放置到上述 <code>northstar-dist</code> 目录。最终的目录结构如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── northstar-dist                               # 程序目录</span></span>
<span class="line"><span>│   ├── northstar-&lt;version&gt;.jar                  # 主程序</span></span>
<span class="line"><span>│   ├── northstar-external-&lt;version&gt;.jar         # 策略包（非必需）</span></span>
<span class="line"><span>│   └── northstar-gateway-xxx-&lt;version&gt;.jar      # 实盘网关包（非必需）</span></span>
<span class="line"><span>└── northstar-env                                # 运行环境目录</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">关于策略包与实盘网关包</p><ul><li><strong>策略包</strong> 是自行实现的，具体可参考知识星球里的策略教程专栏；</li><li><strong>实盘网关包</strong> 地址（注意看版本说明）： <ul><li><a href="https://gitee.com/dromara/northstar-gateway-ctp" target="_blank" rel="noreferrer">CTP</a>【已经过生产环境验证】</li><li><a href="https://gitee.com/dromara/northstar-gateway-tiger" target="_blank" rel="noreferrer">TIGER</a>（仅提供代码示例，需自行完善）</li><li><a href="https://gitee.com/dromara/northstar-gateway-binance" target="_blank" rel="noreferrer">BINANCE</a>【已经过生产环境验证】</li></ul></li><li>不使用实盘交易时，策略包与网关包均非必需，平台内置的 PLAYBACK 与 SIM 渠道开箱即用。</li></ul></div><h2 id="程序启动" tabindex="-1">程序启动 <a class="header-anchor" href="#程序启动" aria-label="Permalink to &quot;程序启动&quot;">​</a></h2><p>在 <code>northstar-dist</code> 目录下，使用 <code>java -jar</code> 便可以启动程序：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;-Dloader.path=$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Denv=prod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> northstar-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">版本</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">号</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.jar</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">注意事项</p><ul><li>要加上环境参数 <code>-Denv=prod</code></li><li>要指定外置依赖路径 <code>&quot;-Dloader.path=$(pwd)&quot;</code>（<code>$(pwd)</code> 是用于输出当前路径的命令，<strong>注意引号</strong>），策略包与网关包依靠它加载</li><li>版本号按实际填，例如 <code>northstar-9.1.0.jar</code></li><li>若使用 Windows 系统，以上命令必须用 <code>powershell</code> 执行，<strong>切勿用 <code>cmd</code> 命令行窗口</strong></li></ul></div><p>启动后，通过浏览器访问：</p><ul><li>若在本地启动，访问 <code>https://localhost/</code></li><li>若在服务器启动，访问 <code>https://你的服务器IP/</code></li></ul><p>启动成功后即可看到登录页，使用默认账号 <code>admin</code> / <code>123456</code> 登录（详见 <a href="/guide/getting-started">快速上手</a>）。</p><h3 id="日志查询" tabindex="-1">日志查询 <a class="header-anchor" href="#日志查询" aria-label="Permalink to &quot;日志查询&quot;">​</a></h3><p>可以在以下路径找到程序运行日志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── northstar-dist   # 程序目录</span></span>
<span class="line"><span>│   ├── logs         # 运行日志目录</span></span>
<span class="line"><span>│   └── data         # 数据文件目录</span></span>
<span class="line"><span>└── northstar-env    # 运行环境目录</span></span></code></pre></div><h2 id="设置数据服务权限" tabindex="-1">设置数据服务权限 <a class="header-anchor" href="#设置数据服务权限" aria-label="Permalink to &quot;设置数据服务权限&quot;">​</a></h2><p>程序在初始状态下，是<strong>没有任何历史数据</strong>的。在以下场景下，程序需要用到历史数据：</p><ul><li>历史回放</li><li>行情复盘</li><li>自动化交易</li></ul><p>历史数据权限<strong>按市场划分</strong>，分别为：</p><ul><li>国内期货</li><li>A 股</li><li>港股</li><li>美股</li><li>币圈</li><li>外汇黄金</li></ul><h3 id="付费使用说明" tabindex="-1">付费使用说明 <a class="header-anchor" href="#付费使用说明" aria-label="Permalink to &quot;付费使用说明&quot;">​</a></h3><p>付费后，用户可以拿到一串<strong>数据服务 token</strong>，然后按以下方式设置即可。</p><h4 id="windows-环境-1" tabindex="-1">Windows 环境 <a class="header-anchor" href="#windows-环境-1" aria-label="Permalink to &quot;Windows 环境&quot;">​</a></h4><ol><li>按下组合功能键 <code>win + R</code>，输入 <code>powershell</code>，然后确定；</li><li>在打开的命令行界面执行：</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setx NS_DS_SECRET </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">数据服务token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>配置完成后，重启电脑才能生效。</strong></p></div><h4 id="linux-环境-1" tabindex="-1">Linux 环境 <a class="header-anchor" href="#linux-环境-1" aria-label="Permalink to &quot;Linux 环境&quot;">​</a></h4><p>执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span></code></pre></div><p>在文末加入以下设置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NS_DS_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">数据服务token</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>保存并退出，然后让配置生效：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.bashrc</span></span></code></pre></div><p>设置完成后重启程序，首页的&quot;已购服务&quot;卡片即可看到订阅的数据服务与到期日。</p><h2 id="更多教程与社区交流" tabindex="-1">更多教程与社区交流 <a class="header-anchor" href="#更多教程与社区交流" aria-label="Permalink to &quot;更多教程与社区交流&quot;">​</a></h2><ul><li>策略开发教程：知识星球策略教程专栏</li><li>使用过程中有任何问题，欢迎在官方交流群提问</li></ul>`,56)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
